//! Precomputed fixed-base tables for edwards448 `[k]B`.
//!
//! Every entry is an affine point stored as `[x_0..x_7, y_0..y_7, t_0..t_7]`
//! — little-endian **56-bit** limbs (the unsaturated 8×u64 representation of
//! [`super::field::Fe`]) of the affine `x`, `y` and `d·x·y` coordinates as
//! canonical residues, the "Niels" form of the `a = +1` mixed addition in
//! [`super::point`] (`Z = 1`, with `d·T` precomputed). No entry is the
//! identity (no stored multiple is a multiple of the odd prime group order
//! `L`), so the `Z = 1` lift is always valid.
//!
//! * `ED448_BASE_TABLE[j][k - 1]` is `[k · 16^(2j)]B` for `j in 0..56`,
//!   `k in 1..=8`: the windows of the constant-time signed radix-16
//!   fixed-base multiplication (`Field::mul_base`), which adds the
//!   odd-position digits from these windows, doubles four times, then adds
//!   the even-position digits.
//! * `ED448_BASE_TOP` is `[16^112]B = [2^448]B`, the carry digit's point.
//! * `ED448_ODD_MULTIPLES[i]` is `[2i + 1]B` for `i in 0..64`, the lookup
//!   table of the width-8 wNAF base ladder in Ed448 verification.
//!
//! Generated by the `#[ignore]`d test
//! `ec::curve448::point::tests::gen_ed448_base_table`
//! (`cargo test --release gen_ed448_base_table -- --ignored --nocapture`);
//! the always-run test `ec::curve448::point::tests::base_table_matches_computed`
//! re-derives every entry from the group law on each test run, so these
//! constants are verified, not trusted.

